-- Контент «Траектории»: предметы, направления, вузы, источники, олимпиады,
-- профили, этапы и льготы.
--
-- ФАЙЛ СГЕНЕРИРОВАН: datasets/parser/build_seed.py (make seed). Руками не править —
-- поменяйте датасет или генератор и перегенерируйте.
--
-- Строк: предметы 9, направления 16, вузы 10,
-- источники 161, олимпиады 72, профили 192, этапы 559, льготы 1374.
--
-- Демонстрационные данные помечены в самих строках: stages.is_demo, льготы и
-- этапы без source_id, источники без verified_at. API по ним отдаёт
-- stages_are_demo и source: null, а интерфейс — «данные уточняются».

-- +goose Up

ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  subject_codes = EXCLUDED.subject_codes;

ON CONFLICT (id) DO UPDATE SET
  short_name = EXCLUDED.short_name,
  name = EXCLUDED.name,
  city = EXCLUDED.city,
  directions = EXCLUDED.directions,
  ege_note = EXCLUDED.ege_note,
  rules_url = EXCLUDED.rules_url,
  rules_verified_at = EXCLUDED.rules_verified_at;

ON CONFLICT (id) DO UPDATE SET
  kind = EXCLUDED.kind,
  title = EXCLUDED.title,
  url = EXCLUDED.url,
  verified_at = EXCLUDED.verified_at;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  organizer = EXCLUDED.organizer,
  kind = EXCLUDED.kind,
  official_url = EXCLUDED.official_url,
  format = EXCLUDED.format,
  final_city = EXCLUDED.final_city,
  final_region_code = EXCLUDED.final_region_code;

ON CONFLICT (id) DO UPDATE SET
  olympiad_id = EXCLUDED.olympiad_id,
  subject_code = EXCLUDED.subject_code,
  profile_slug = EXCLUDED.profile_slug,
  profile_name = EXCLUDED.profile_name,
  level = EXCLUDED.level,
  school_year = EXCLUDED.school_year,
  grades_from = EXCLUDED.grades_from,
  grades_to = EXCLUDED.grades_to,
  source_id = EXCLUDED.source_id;

ON CONFLICT (id) DO UPDATE SET
  olympiad_profile_id = EXCLUDED.olympiad_profile_id,
  kind = EXCLUDED.kind,
  title = EXCLUDED.title,
  starts_at = EXCLUDED.starts_at,
  ends_at = EXCLUDED.ends_at,
  deadline_at = EXCLUDED.deadline_at,
  is_online = EXCLUDED.is_online,
  is_demo = EXCLUDED.is_demo,
  source_id = EXCLUDED.source_id;

ON CONFLICT (id) DO UPDATE SET
  olympiad_profile_id = EXCLUDED.olympiad_profile_id,
  university_id = EXCLUDED.university_id,
  admission_year = EXCLUDED.admission_year,
  benefit = EXCLUDED.benefit,
  extra_points = EXCLUDED.extra_points,
  ege_min = EXCLUDED.ege_min,
  diploma_grades = EXCLUDED.diploma_grades,
  note = EXCLUDED.note,
  source_id = EXCLUDED.source_id;

-- +goose Down
-- Откат удаляет весь контент. Если на него уже ссылаются пользовательские
-- данные (трекер, вузы траектории), откат упадёт на внешнем ключе — так и надо.
DELETE FROM benefits;
DELETE FROM stages;
DELETE FROM olympiad_profiles;
DELETE FROM olympiads;
DELETE FROM sources;
DELETE FROM universities;
DELETE FROM directions;
DELETE FROM subjects;
